Q: Issue passing data from API call in SwiftUI MVVM pattern A: <p>Suppose API is : &quot;<a href="https://jsonplaceholder.typicode.com/users" rel="nofollow noreferrer">https://jsonplaceholder.typicode.com/users</a>&quot;</p>
<p>Step 1 : Model<br />
Create Model Folder<br />
Create User.swift</p>
<pre><code>import Foundation

struct User: Codable {
    let id: Int
    let name: String
    let username: String
    let email: String
    let phone: String
    let website: String
}
</code></pre>
<p>Step 2: NetWork<br />
Create NetWork Folder<br />
Create NetworkError.swift</p>
<pre><code>import Foundation

enum NetworkError: Error {
    case invalidURL
    case invalidResponse
    case serverError(Int)
    case decodingError
    case unknown
}
</code></pre>
<p>Create NetworkService.swift</p>
<pre><code>import Foundation

final class NetworkService: NetworkServiceProtocol {

    private let urlString = &quot;https://jsonplaceholder.typicode.com/users&quot;

    func fetchUsers() async throws -&gt; [User] {

        // Create URL
        guard let url = URL(string: urlString) else {
            throw NetworkError.invalidURL
        }

        // API call
        let (data, response) = try await URLSession.shared.data(from: url)

        // Check response
        guard let httpResponse = response as? HTTPURLResponse else {
            throw NetworkError.invalidResponse
        }

        // Check status code
        guard 200...299 ~= httpResponse.statusCode else {
            throw NetworkError.serverError(httpResponse.statusCode)
        }

        // Parse JSON
        do {
            let users = try JSONDecoder().decode(
                [User].self,
                from: data
            )

            return users

        } catch {
            throw NetworkError.decodingError
        }
    }
}
</code></pre>
<p>Create NetworkServiceProtocol.swift</p>
<pre><code>import Foundation
protocol NetworkServiceProtocol {
    func fetchUsers() async throws -&gt; [User]
}
</code></pre>
<p>Step 3: ViewModels<br />
Create ViewModels Folder<br />
Create UsersViewModel.swift</p>
<pre><code>import Foundation

@MainActor
final class UsersViewModel {

    // MARK: - Properties

    private let networkService: NetworkServiceProtocol

    private var fetchTask: Task&lt;Void, Never&gt;?

    private(set) var users: [User] = []

    private(set) var filteredUsers: [User] = []

    // MARK: - Callbacks

    var onUsersUpdated: (() -&gt; Void)?

    var onLoadingChanged: ((Bool) -&gt; Void)?

    var onError: ((String) -&gt; Void)?

    // MARK: - Init

    init(networkService: NetworkServiceProtocol) {
        self.networkService = networkService
    }

    // MARK: - Fetch Users

    func fetchUsers() {

        // Cancel previous request
        fetchTask?.cancel()

        onLoadingChanged?(true)

        fetchTask = Task { [weak self] in

            guard let self else {
                return
            }

            do {

                let users =
                    try await networkService.fetchUsers()

                // Check cancellation
                try Task.checkCancellation()

                self.users = users
                self.filteredUsers = users

                self.onLoadingChanged?(false)

                self.onUsersUpdated?()

            } catch is CancellationError {

                self.onLoadingChanged?(false)

            } catch {

                self.onLoadingChanged?(false)

                self.onError?(
                    &quot;Unable to load users. Please try again.&quot;
                )
            }
        }
    }

    // MARK: - Cancel

    func cancelRequest() {
        fetchTask?.cancel()
        fetchTask = nil
    }

    deinit {
        fetchTask?.cancel()
    }
}
</code></pre>
<p>Step : 4 Views<br />
Create Views Folder<br />
Create custom cell using XIB UserTableViewCell</p>
<pre><code>import UIKit

class UserTableViewCell: UITableViewCell {

    @IBOutlet weak var nameLBL: UILabel!
    @IBOutlet weak var usernameLBL: UILabel!
    @IBOutlet weak var emailLBL: UILabel!

    override func awakeFromNib() {
        super.awakeFromNib()
        // Initialization code
    }

    override func setSelected(_ selected: Bool, animated: Bool) {
        super.setSelected(selected, animated: animated)

        // Configure the view for the selected state
    }

    func configure(with user: User) {
        nameLBL.text = user.name
        usernameLBL.text = &quot;@\(user.username)&quot;
        emailLBL.text = user.email
    }
}
</code></pre>
<p>Step : 5 ViewController<br />
Create Controller Folder</p>
<pre><code>import UIKit

class ViewController: UIViewController {

    @IBOutlet weak var TBL: UITableView!

        private let activityIndicator = UIActivityIndicatorView(
            style: .large
        )

        private let viewModel: UsersViewModel

        // MARK: - Init


    init(viewModel: UsersViewModel) {

        self.viewModel = viewModel

        super.init(
            nibName: nil,
            bundle: nil
        )
    }

    required init?(coder: NSCoder) {

        let networkService = NetworkService()

        self.viewModel = UsersViewModel(
            networkService: networkService
        )

        super.init(coder: coder)
    }

    override func viewDidLoad() {
        super.viewDidLoad()

        setupUI()

        setupActivityIndicator()

        setupBindings()

        viewModel.fetchUsers()
    }

    override func viewDidDisappear(
            _ animated: Bool
        ) {

            super.viewDidDisappear(animated)

            viewModel.cancelRequest()
        }


}

extension ViewController {

    private func setupUI() {

        view.backgroundColor = .systemBackground
        title = &quot;Users&quot;

        TBL.register( UINib( nibName: &quot;UserTableViewCell&quot;, bundle: nil ), forCellReuseIdentifier: &quot;UserTableViewCell&quot;)
        TBL.rowHeight = UITableView.automaticDimension
        TBL.estimatedRowHeight = 80
    }
}


//TBL
extension ViewController: UITableViewDataSource {

    func tableView( _ tableView: UITableView, numberOfRowsInSection section: Int ) -&gt; Int {

        return viewModel.users.count
    }

    func tableView( _ tableView: UITableView, cellForRowAt indexPath: IndexPath ) -&gt; UITableViewCell {

        guard let cell = tableView.dequeueReusableCell( withIdentifier: &quot;UserTableViewCell&quot;, for: indexPath ) as? UserTableViewCell else {

            return UITableViewCell()
        }

        let user = viewModel.users[indexPath.row]

        cell.configure(with: user)

        return cell
    }
}

// activityIndicator
extension ViewController {

    private func setupActivityIndicator() {

        view.addSubview(activityIndicator)

        activityIndicator.translatesAutoresizingMaskIntoConstraints = false

        NSLayoutConstraint.activate([

            activityIndicator.centerXAnchor.constraint(
                equalTo: view.centerXAnchor
            ),

            activityIndicator.centerYAnchor.constraint(
                equalTo: view.centerYAnchor
            )
        ])
    }
}

//setupBindings
extension ViewController {

    private func setupBindings() {

        viewModel.onUsersUpdated = { [weak self] in

            self?.TBL.reloadData()
        }

        viewModel.onLoadingChanged = {
            [weak self] isLoading in

            if isLoading {

                self?.activityIndicator.startAnimating()

            } else {

                self?.activityIndicator.stopAnimating()
            }
        }

        viewModel.onError = {
            [weak self] message in

            self?.showError(message)
        }
    }

    private func showError(_ message: String) {

        let alert = UIAlertController(
            title: &quot;Error&quot;,
            message: message,
            preferredStyle: .alert
        )

        alert.addAction(
            UIAlertAction(
                title: &quot;Retry&quot;,
                style: .default
            ) { [weak self] _ in

                self?.viewModel.fetchUsers()
            }
        )

        alert.addAction(
            UIAlertAction(
                title: &quot;Cancel&quot;,
                style: .cancel
            )
        )

        present(
            alert,
            animated: true
        )
    }
}
</code></pre>

